(()=>{try{const b64=window.__aionV08Payload||'';if(!b64)throw new Error('AION v0.8 payload missing');const bin=atob(b64);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const html=new TextDecoder('utf-8').decode(bytes);document.open();document.write(html);document.close();}catch(err){console.error(err);document.body.innerHTML='<main style="font-family:-apple-system;background:#090b0f;color:#f5f7fa;min-height:100vh;padding:32px"><h2>AION Service v0.8</h2><p>Не удалось запустить прототип.</p><pre style="white-space:pre-wrap;color:#c7ced8">'+String(err&&err.message||err)+'</pre></main>';}})();
